(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  out.nav = [...document.querySelectorAll('header a')].map((a) => a.textContent.trim());
  const entry = [...document.querySelectorAll('header a')].find((a) => a.textContent.trim() === '工具箱');
  out.hasToolboxEntry = !!entry;
  entry?.click();
  await sleep(3200);
  out.path = location.pathname;
  const libBtn = [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库');
  out.libraryEntry = !!libBtn;
  libBtn?.click();
  await sleep(2400);
  out.title = document.querySelector('.lib-title')?.textContent || null;
  out.cards = document.querySelectorAll('.lib-card').length;
  out.images = [...document.querySelectorAll('.lib-card img')].filter((i) => i.naturalWidth > 0).length;
  out.intro = !!document.querySelector('.lib-intro');
  return JSON.stringify(out);
})()
